package com.cpf.starter.grpc;import io.grpc.*;import io.grpc.netty.shaded.io.grpc.netty.NettyChannelBuilder;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.*;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.Bean;@AutoConfiguration @EnableConfigurationProperties(CpfGrpcProperties.class) @ConditionalOnProperty(prefix="cpf.integration.grpc",name="enabled",havingValue="true") public class CpfGrpcAutoConfiguration {@Bean(destroyMethod="shutdown") @ConditionalOnMissingBean ManagedChannel cpfGrpcManagedChannel(CpfGrpcProperties p){p.validate();var b=NettyChannelBuilder.forTarget(p.getTarget()).maxInboundMessageSize(p.getMaxInboundBytes());if(p.isPlaintext())b.usePlaintext();return b.build();}@Bean CpfGrpcClient cpfGrpcClient(ManagedChannel c,CpfGrpcProperties p){return new CpfGrpcClient(c,p);}}
